          { kind: "fill", promptUk: "Додайте const до параметра типу", promptEn: "Add const to the type parameter", language: "typescript", code: "function tuple<___ T extends unknown[]>(...xs: T): T { return xs; }", accepted: ["const"], caseSensitive: true, explanationUk: "const перед T зберігає літеральний кортеж.", explanationEn: "const before T keeps a literal tuple." },
          { kind: "read", promptUk: "Який тип поверне tuple('on', 'off') з const T?", promptEn: "What type does tuple('on', 'off') return with const T?", language: "typescript", code: "function tuple<const T extends unknown[]>(...xs: T): T { return xs; }", options: ["readonly ['on', 'off'] (або еквівалентний кортеж літералів)", "string[]", "any[]", "[string, string] без літералів"], correctIndex: 0, explanationUk: "Літерали аргументів зберігаються.", explanationEn: "The argument literals are preserved." }
